import type {
  LegacyStorage,
  ProviderBCommitBatch,
  ProviderBReservationRow,
  ProviderBStorage,
  Reservation,
  ReservationCommit,
  ReservationEvent,
  Service,
  ServiceResponse,
  Stock,
} from "./types";
import {
  decimalText,
  decodeReservation,
  decodeStock,
  isId,
  isQuantity,
  isRecord,
  isRevision,
  parseCanonicalDecimal,
} from "./validation";

type Command =
  | { op: "getAvailability"; sku: string }
  | { op: "getReservation"; reservationId: string }
  | { op: "reserve"; reservationId: string; sku: string; quantity: number };

function parseCommand(raw: unknown): Command | undefined {
  if (!isRecord(raw)) return undefined;
  switch (raw.op) {
    case "getAvailability":
      return isId(raw.sku) ? { op: raw.op, sku: raw.sku } : undefined;
    case "getReservation":
      return isId(raw.reservationId)
        ? { op: raw.op, reservationId: raw.reservationId } : undefined;
    case "reserve":
      return isId(raw.reservationId) && isId(raw.sku) && isQuantity(raw.quantity)
        ? { op: raw.op, reservationId: raw.reservationId, sku: raw.sku, quantity: raw.quantity }
        : undefined;
    default:
      return undefined;
  }
}

export function error(status: 400 | 404 | 409 | 500, code: string): ServiceResponse {
  return { status, body: { code } };
}

export function reservationResponse(status: 200 | 201, reservation: Reservation): ServiceResponse {
  return {
    status,
    body: {
      reservationId: reservation.reservationId,
      sku: reservation.sku,
      quantity: reservation.quantity,
    },
  };
}

type StockRead =
  | { kind: "found"; stock: Stock }
  | { kind: "missing" }
  | { kind: "unavailable" };

type ReservationRead =
  | { kind: "found"; reservation: Reservation }
  | { kind: "missing" }
  | { kind: "unavailable" };

type CommitOutcome =
  | { kind: "committed" }
  | { kind: "revisionConflict" }
  | { kind: "unavailable" };

type ReservationBackend = {
  readStock(sku: string): Promise<StockRead>;
  readReservation(reservationId: string): Promise<ReservationRead>;
  commitReservation(change: ReservationCommit): Promise<CommitOutcome>;
};

function createReservationHandler(backend: ReservationBackend): Service {
  return {
    async handle(raw) {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");
      try {
        if (command.op === "getAvailability") {
          const stockRead = await backend.readStock(command.sku);
          if (stockRead.kind === "missing") return error(404, "stock_not_found");
          if (stockRead.kind === "unavailable") return error(500, "storage_unavailable");
          const stock = stockRead.stock;
          return {
            status: 200,
            body: {
              sku: stock.sku,
              totalUnits: stock.totalUnits,
              reservedUnits: stock.reservedUnits,
              availableUnits: stock.totalUnits - stock.reservedUnits,
            },
          };
        }

        const reservationRead = await backend.readReservation(command.reservationId);
        if (reservationRead.kind === "unavailable") return error(500, "storage_unavailable");
        const existing = reservationRead.kind === "found" ? reservationRead.reservation : undefined;
        if (command.op === "getReservation") {
          return existing ? reservationResponse(200, existing) : error(404, "reservation_not_found");
        }
        if (existing) {
          return existing.sku === command.sku && existing.quantity === command.quantity
            ? reservationResponse(200, existing)
            : error(409, "reservation_conflict");
        }

        const stockRead = await backend.readStock(command.sku);
        if (stockRead.kind === "missing") return error(404, "stock_not_found");
        if (stockRead.kind === "unavailable") return error(500, "storage_unavailable");
        const stock = stockRead.stock;
        if (stock.totalUnits - stock.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }
        const nextRevision = stock.revision + 1;
        if (!isRevision(nextRevision)) return error(500, "storage_unavailable");
        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const event: ReservationEvent = {
          eventId: "reservation.created:" + reservation.reservationId,
          type: "reservation.created",
          reservationId: reservation.reservationId,
          sku: reservation.sku,
          quantity: reservation.quantity,
        };
        const outcome = await backend.commitReservation({
          expectedRevision: stock.revision,
          nextStock: {
            ...stock,
            reservedUnits: stock.reservedUnits + command.quantity,
            revision: nextRevision,
          },
          reservation,
          events: [event],
        });
        if (outcome.kind === "revisionConflict") return error(409, "commit_conflict");
        if (outcome.kind === "unavailable") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

export function createReservationService({ storage }: { storage: LegacyStorage }): Service {
  return createReservationHandler({
    async readStock(sku) {
      const rawStock = await storage.getStock(sku);
      if (rawStock === undefined) return { kind: "missing" };
      const stock = decodeStock(rawStock);
      if (!stock || stock.sku !== sku) return { kind: "unavailable" };
      return { kind: "found", stock };
    },
    async readReservation(reservationId) {
      const rawReservation = await storage.getReservation(reservationId);
      if (rawReservation === undefined) return { kind: "missing" };
      const reservation = decodeReservation(rawReservation);
      if (!reservation || reservation.reservationId !== reservationId) return { kind: "unavailable" };
      return { kind: "found", reservation };
    },
    async commitReservation(change) {
      const outcome = await storage.commitReservation(change);
      if (outcome === "committed") return { kind: "committed" };
      if (outcome === "revision_conflict") return { kind: "revisionConflict" };
      return { kind: "unavailable" };
    },
  });
}

type ProviderBRead =
  | { kind: "found"; value: unknown }
  | { kind: "missing" }
  | { kind: "unavailable" };

function decodeProviderBRead(value: unknown): ProviderBRead {
  if (!isRecord(value) || typeof value.ok !== "boolean") return { kind: "unavailable" };
  if (value.ok) {
    return "value" in value && value.value !== null && value.value !== undefined
      ? { kind: "found", value: value.value }
      : { kind: "unavailable" };
  }
  if (!isRecord(value.error) || typeof value.error.reason !== "string") return { kind: "unavailable" };
  if (value.error.reason === "NO_SUCH_KEY") return { kind: "missing" };
  return { kind: "unavailable" };
}

function decodeProviderBStockRow(value: unknown, requestedKey: string): Stock | undefined {
  if (!isRecord(value) || !isId(value.itemKey) || value.itemKey !== requestedKey) return undefined;
  const totalUnits = parseCanonicalDecimal(value.onHandText);
  const reservedUnits = parseCanonicalDecimal(value.heldText);
  const revision = parseCanonicalDecimal(value.revisionText);
  const stock = decodeStock({
    sku: value.itemKey,
    totalUnits,
    reservedUnits,
    revision,
  });
  return stock && stock.sku === requestedKey ? stock : undefined;
}

function decodeProviderBReservationRow(value: unknown, requestedKey: string): Reservation | undefined {
  if (!isRecord(value) || !isId(value.bookingKey) || !isId(value.itemKey) ||
      value.bookingKey !== requestedKey) return undefined;
  const quantity = parseCanonicalDecimal(value.unitsText);
  const reservation = decodeReservation({
    reservationId: value.bookingKey,
    sku: value.itemKey,
    quantity,
  });
  return reservation && reservation.reservationId === requestedKey ? reservation : undefined;
}

function providerBReservationRow(reservation: Reservation): ProviderBReservationRow {
  return {
    bookingKey: reservation.reservationId,
    itemKey: reservation.sku,
    unitsText: decimalText(reservation.quantity),
  };
}

function providerBBatch(change: ReservationCommit): ProviderBCommitBatch {
  const reservationRow = providerBReservationRow(change.reservation);
  return {
    expectedRevisionText: decimalText(change.expectedRevision),
    stockRow: {
      itemKey: change.nextStock.sku,
      onHandText: decimalText(change.nextStock.totalUnits),
      heldText: decimalText(change.nextStock.reservedUnits),
      revisionText: decimalText(change.nextStock.revision),
    },
    reservationRow,
    outboxRows: [{
      key: "reservation.created:" + change.reservation.reservationId,
      category: "reservation",
      name: "created",
      payload: reservationRow,
    }],
  };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return createReservationHandler({
    async readStock(sku) {
      const read = decodeProviderBRead(await storage.read({ collection: "inventory", key: sku }));
      if (read.kind !== "found") return read;
      const stock = decodeProviderBStockRow(read.value, sku);
      return stock ? { kind: "found", stock } : { kind: "unavailable" };
    },
    async readReservation(reservationId) {
      const read = decodeProviderBRead(await storage.read({ collection: "reservations", key: reservationId }));
      if (read.kind !== "found") return read;
      const reservation = decodeProviderBReservationRow(read.value, reservationId);
      return reservation ? { kind: "found", reservation } : { kind: "unavailable" };
    },
    async commitReservation(change) {
      try {
        const outcome = await storage.commitBatch(providerBBatch(change));
        if (outcome === "applied") return { kind: "committed" };
        if (outcome === "revision_conflict") return { kind: "revisionConflict" };
        return { kind: "unavailable" };
      } catch {
        return { kind: "unavailable" };
      }
    },
  });
}

